    constructor(IERC20 _token) {
        token = _token;
    }

    function demonstrateVulnerability(address from, uint256 amount) external {
        // This demonstrates the vulnerability:
        // 1. First transferFrom call
        token.transferFrom(from, address(this), amount);

        // At this point, if there was a callback after _transfer but before _approve,
        // we could reenter here and call transferFrom again with the same allowance
        // The allowance hasn't been reduced yet!

